// SLATE-FILECHECK-DEFINES DEFAULT

/* Test whether jump threading doesn't ICE if redirecting the jump to exit
   block.  */

extern int bar ();
extern void baz ();

void foo ()
{
  int x;

  do
    {
      if ((x = bar ()) == 1)
	baz ();
    }
  while (x == 1);
}

